@startuml

class WebPortal {
  + versionNumber : string
  + urlAddress : string
}

class Building {
  + id : int
  + name : string
  + energyClass : string
  + address : string
  + yearOfConstruction : int
}

class AdditionalEntry {
  + name : string
  + isPublic : boolean
}

class TextualEntry extends AdditionalEntry {}

class NumericalEntry extends AdditionalEntry {
  + value : double
  + unit : string
}

class Image {
  + fileName : string
}

class User {
  + userName : string
  + email : string
  + password : string
  + isActivated : boolean
}

class Administrator extends User {
  + idCardNumber : string
}

class Comment {
  + text : string
}

WebPortal "1" -- "*" Building
Building "1" *-- "*" AdditionalEntry
Building "1" *-- "*" Image
Building "1" -- "0..1" Image : profile photo
Building "1" -- "*" Comment
User "1" -- "*" Building : owner
User "1" -- "*" Comment : author
WebPortal "1" -- "*" User : visitors/registered users

@enduml

